<?php $editing=isset($record); $row=$record ?? []; ?><form class="stack" action="/career/<?= e($formType) ?><?= $editing ? '/'.e($row['id']).'/edit' : '' ?>" method="post"><?= csrf_field() ?>
<?php if ($formType==='applications'): ?>
<label>Organization<input name="organization" value="<?= e($row['organization'] ?? '') ?>" maxlength="200" required></label><label>Role<input name="role" value="<?= e($row['role'] ?? '') ?>" maxlength="200" required></label><label>Application link or reference<input name="resource" value="<?= e($row['resource'] ?? '') ?>" maxlength="1000"></label><label>Status<select name="status"><?php foreach (CareerService::APPLICATION_STATUSES as $key=>$label): ?><option value="<?= e($key) ?>" <?= ($row['status'] ?? 'saved')===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Applied date<input type="date" name="applied_date" value="<?= e($row['applied_date'] ?? '') ?>"></label><label>Application deadline<input type="date" name="deadline" value="<?= e($row['deadline'] ?? '') ?>"></label><label>Next interview<input type="datetime-local" name="interview_at" value="<?= e(str_replace(' ','T',$row['interview_at'] ?? '')) ?>"></label>
<?php else: ?>
<label><?= $formType==='skills' ? 'Skill' : 'Course' ?> name<input name="name" value="<?= e($row['name'] ?? '') ?>" maxlength="<?= $formType==='skills' ? 150 : 200 ?>" required></label>
<?php if ($formType==='courses'): ?><label>Provider<input name="provider" value="<?= e($row['provider'] ?? '') ?>" maxlength="200"></label><label>Course link or reference<input name="resource" value="<?= e($row['resource'] ?? '') ?>" maxlength="1000"></label><label>Related skill<select name="skill_id"><option value="">No linked skill</option><?php foreach ($skills as $skill): ?><option value="<?= e($skill['id']) ?>" <?= ($row['skill_id'] ?? null)===$skill['id'] ? 'selected' : '' ?>><?= e($skill['name']) ?></option><?php endforeach; ?></select></label><label>Status<select name="status"><?php foreach (CareerService::COURSE_STATUSES as $key=>$label): ?><option value="<?= e($key) ?>" <?= ($row['status'] ?? 'planned')===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><?php endif; ?>
<label><?= $formType==='skills' ? 'Self-assessed progress' : 'Course completion' ?> %<input name="progress" type="number" min="0" max="100" value="<?= e($row['progress'] ?? 0) ?>" required></label><label>Target date<input type="date" name="<?= $formType==='skills' ? 'target_date' : 'due_date' ?>" value="<?= e($formType==='skills' ? ($row['target_date'] ?? '') : ($row['due_date'] ?? '')) ?>"></label>
<?php endif; ?>
<label>Notes<textarea name="notes" maxlength="<?= $formType==='applications' ? 5000 : 3000 ?>" rows="3"><?= e($row['notes'] ?? '') ?></textarea></label><button><?= $editing ? 'Save changes' : 'Add '.e(match($formType) {'skills'=>'skill','courses'=>'course',default=>'application'}) ?></button></form>
